#ifdef CONFIG_NXPLAYER_INCLUDE_SYSTEM_RESET
  {
    "reset",
    "",
    nxplayer_cmd_reset,
    NXPLAYER_HELP_TEXT("Perform a HW reset")
  },
#endif
#ifndef CONFIG_AUDIO_EXCLUDE_PAUSE_RESUME
  {
    "resume",
    "",
