};

static const int g_nxplayer_cmd_count = sizeof(g_nxplayer_cmds) /
                                        sizeof(struct mp_cmd_s);

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: nxplayer_cmd_play
 *
 *   nxplayer_cmd_play() plays the specified media file using the nxplayer
 *   context.
 *
 ****************************************************************************/

static int nxplayer_cmd_play(FAR struct nxplayer_s *pplayer, char *parg)
{
  int ret;

  /* Try to play the file specified */

  ret = nxplayer_playfile(pplayer, parg, AUDIO_FMT_UNDEF, AUDIO_FMT_UNDEF);

  /* nxplayer_playfile returned values:
   *
   *   OK         File is being played
   *   -EBUSY     The media device is busy
   *   -ENOSYS    The media file is an unsupported type
   *   -ENODEV    No audio device suitable to play the media type
   *   -ENOENT    The media file was not found
   */

  switch (-ret)
    {
      case OK:
        break;

      case ENODEV:
        printf("No suitable Audio Device found\n");
        break;

      case EBUSY:
        printf("Audio device busy\n");
        break;

      case ENOENT:
        printf("File %s not found\n", parg);
        break;

      case ENOSYS:
        printf("Unknown audio format\n");
        break;

      default:
        printf("Error playing file: %d\n", -ret);
        break;
    }

  return ret;
}

/****************************************************************************
 * Name: nxplayer_cmd_playraw
 *
 *   nxplayer_cmd_play() plays the raw data file using the nxplayer
 *   context.
 *
 ****************************************************************************/

static int nxplayer_cmd_playraw(FAR struct nxplayer_s *pplayer, char *parg)
{
  int ret;
  int channels = 0;
  int bpsamp = 0;
  int samprate = 0;
  int chmap = 0;
  char filename[128];

  sscanf(parg, "%s %d %d %d %d", filename, &channels, &bpsamp,
                                 &samprate, &chmap);

  /* Try to play the file specified */

  ret = nxplayer_playraw(pplayer, filename, AUDIO_FMT_PCM, 0,
                         channels, bpsamp, samprate, chmap);

  /* nxplayer_playraw returned values:
   *
   *   OK         File is being played
   *   -EBUSY     The media device is busy
   *   -ENOSYS    The media file is an unsupported type
   *   -ENODEV    No audio device suitable to play the media type
   *   -ENOENT    The media file was not found
   */

  switch (-ret)
    {
      case OK:
        break;

      case ENODEV:
        printf("No suitable Audio Device found\n");
        break;

      case EBUSY:
        printf("Audio device busy\n");
        break;

      case ENOENT:
        printf("File %s not found\n", filename);
        break;

      case ENOSYS:
        printf("Unknown audio format\n");
        break;

      default:
        printf("Error playing file: %d\n", -ret);
        break;
    }

  return ret;
}

/****************************************************************************
 * Name: nxplayer_cmd_tone
 *
 *   nxplayer_cmd_tone() plays the tone using the nxplayer
 *   context.
 *
 ****************************************************************************/

static int nxplayer_cmd_tone(FAR struct nxplayer_s *pplayer, char *parg)
{
  int ret;
  uint32_t samprate  = 0;
  uint32_t pitchfreq = 0;
  uint32_t duration  = 0;

  sscanf(parg, "%" PRIu32 " %" PRIu32 " %" PRIu32 "",
         &samprate, &duration, &pitchfreq);

  /* Try to play tone */

  ret = nxplayer_playtone(pplayer, samprate, pitchfreq, duration);

  /* nxplayer_playtone returned values:
   *
   *   OK         Tone is being played
   *   -EBUSY     The media device is busy
   *   -ENODEV    No audio device suitable to play the media type
   */

  switch (-ret)
    {
      case OK:
        break;

      case ENODEV:
        printf("No suitable Audio Device found\n");
        break;

      case EBUSY:
        printf("Audio device busy\n");
        break;

      default:
        printf("Error playing tone: %d\n", -ret);
        break;
