static void put_le16(FAR uint8_t *p, uint16_t v)
{
  p[0] = (uint8_t)(v & 0xff);
  p[1] = (uint8_t)((v >> 8) & 0xff);
}

static void put_le32(FAR uint8_t *p, uint32_t v)
{
  p[0] = (uint8_t)(v & 0xff);
  p[1] = (uint8_t)((v >> 8) & 0xff);
  p[2] = (uint8_t)((v >> 16) & 0xff);
  p[3] = (uint8_t)((v >> 24) & 0xff);
}

/* Write a real, valid 16-bit PCM WAV file (mono, TTS_SAMPLE_RATE) from the
 * embedded speech samples produced by the host-side TTS.
 *
 * Layout: 44-byte RIFF/WAVE header + raw PCM samples.
 *   RIFF chunk : "RIFF" + (36 + dataSize) + "WAVE"
 *   fmt  chunk : PCM(1) / channels / sampleRate / byteRate / blockAlign /
 *                bitsPerSample
 *   data chunk : "data" + dataSize
 *
 * Returns 0 on success, -1 on failure.
 */

static int write_wav(FAR const char *path, FAR const int16_t *pcm,
                     size_t nsamp)
{
  FILE *fp;
  uint8_t hdr[44];
  uint8_t sample[2];
  size_t i;
  uint32_t datasize = (uint32_t)nsamp * (TTS_BPS / 8);
  uint32_t byterate = TTS_SAMPLE_RATE * TTS_CHANNELS * (TTS_BPS / 8);
  uint16_t blockalign = TTS_CHANNELS * (TTS_BPS / 8);

  memset(hdr, 0, sizeof(hdr));

  /* RIFF header */

  memcpy(hdr + 0,  "RIFF", 4);
  put_le32(hdr + 4, 36 + datasize);
  memcpy(hdr + 8,  "WAVE", 4);

  /* fmt chunk */

  memcpy(hdr + 12, "fmt ", 4);
  put_le32(hdr + 16, 16);                  /* fmt chunk size       */
  put_le16(hdr + 20, 1);                   /* PCM format           */
  put_le16(hdr + 22, TTS_CHANNELS);        /* mono                 */
  put_le32(hdr + 24, TTS_SAMPLE_RATE);     /* sample rate          */
  put_le32(hdr + 28, byterate);            /* byte rate            */
  put_le16(hdr + 32, blockalign);          /* block align          */
  put_le16(hdr + 34, TTS_BPS);             /* bits per sample      */

  /* data chunk */

  memcpy(hdr + 36, "data", 4);
  put_le32(hdr + 40, datasize);

  fp = fopen(path, "wb");
  if (fp == NULL)
    {
      printf("ai_glasses: ERROR: cannot create %s\n", path);
      return -1;
    }

  if (fwrite(hdr, 1, sizeof(hdr), fp) != sizeof(hdr))
    {
      printf("ai_glasses: ERROR: failed to write WAV header\n");
      fclose(fp);
      return -1;
    }

  /* Raw speech samples (written little-endian, byte by byte) */

  for (i = 0; i < nsamp; i++)
    {
      uint16_t val = (uint16_t)pcm[i];

      sample[0] = (uint8_t)(val & 0xff);
      sample[1] = (uint8_t)((val >> 8) & 0xff);
      if (fwrite(sample, 1, 2, fp) != 2)
        {
          printf("ai_glasses: ERROR: failed to write WAV data\n");
          fclose(fp);
          return -1;
        }
    }

  fclose(fp);
  printf("ai_glasses: speech WAV generated: %s (%u bytes, %u samples)\n",
         path, (unsigned int)(datasize + sizeof(hdr)),
         (unsigned int)nsamp);
  return 0;
}

/* Pick the pre-rendered speech clip that matches a recognized text and write
 * it out as a WAV.  If no exact clip exists yet (e.g. the recognizer was
 * taught a new phrase), fall back to the first entry so the pipeline still
 * produces audible output.
 *
 * Returns 0 on success, -1 on failure.
 */

static int speak_text(FAR const char *recognized)
{
  FAR const struct tts_phrase_s *match;
  int i;

  match = NULL;
  for (i = 0; i < TTS_PHRASE_COUNT; i++)
    {
      if (strcmp(recognized, g_tts_phrases[i].text) == 0)
        {
          match = &g_tts_phrases[i];
          break;
        }
    }

  if (match == NULL)
    {
      printf("ai_glasses: no speech clip for \"%s\", using fallback\n",
             recognized);
      match = &g_tts_phrases[0];
    }

  printf("ai_glasses: speaking \"%s\"\n", match->text);
  return write_wav(WAV_PATH, match->pcm, match->nsamp);
}

/* Play a WAV file through the registered audio device.  nxplayer in this
 * tree is interactive-only (it ignores command line file arguments), so we
 * drive it non-interactively by feeding it a small command file on stdin.
 */

static int play_wav(void)
{
  FILE *fp;
  int ret;

  fp = fopen(NXPLAYER_CMD, "w");
  if (fp == NULL)
    {
      printf("ai_glasses: ERROR: cannot create %s\n", NXPLAYER_CMD);
      return -1;
    }

  fprintf(fp, "play %s\nq\n", WAV_PATH);
  fclose(fp);

  printf("ai_glasses: play via: nxplayer < %s\n", NXPLAYER_CMD);
  ret = system("nxplayer < " NXPLAYER_CMD);
  printf("ai_glasses: nxplayer returned %d\n", ret);
  return ret;
}

/* Simulate an on-device image-recognition inference.  In a real product the
 * camera frame would be fed to a neural-network accelerator and the top
 * classification returned.  Here we just return a canned result string so the
 * surrounding announce/voice flow can be exercised end to end.
 */

static FAR const char *image_recognition_demo(void)
{
  static const char *result = "Detected: person, 95% confidence";

  return result;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * ai_glasses_main
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  FAR const char *recognized;
  int ret;

  printf("Hello, AI Glasses World!!\n");

  /* Run the (simulated) image recognition and read the result aloud using
   * the pre-rendered speech clip for the recognized text.
   */

  recognized = image_recognition_demo();
  printf("ai_glasses: recognition result: %s\n", recognized);

  ret = speak_text(recognized);
  if (ret < 0)
    {
      printf("ai_glasses: FAILED to produce speech WAV (%d)\n", ret);
      return ret;
    }

  /* Push the speech WAV to the audio device.  On targets without a codec
   * (e.g. the qemu board registers only AUDIO_NULL) nxplayer reports that no
   * audio device is available and exits; the WAV itself stays in /data for
   * inspection.
   */

  ret = play_wav();
  printf("ai_glasses: recognition result spoken (WAV at %s, playback %s)\n",
         WAV_PATH, ret == 0 ? "OK" : "not audible on this board");

  return 0;
}

