                                    FAR uint8_t *addr,
                                    uint32_t size)
{
  FAR qemu_camera_priv_t *priv = (FAR qemu_camera_priv_t *)data;

  if (addr == NULL || ((uintptr_t)addr & 0x1f))
    {
      return -EINVAL;
    }

