/* Grab a single QVGA RGB565 frame from the board's virtual camera device
 * using the same V4L2 USERPTR ring-buffer flow as the NuttX camera example.
 * On success *out is a freshly allocated frame the caller must free().
 */

static int camera_grab(FAR uint8_t **out, FAR uint32_t *outsize)
{
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer q;
  FAR uint8_t *buf;
  int fd;
  int ret;

  *out = NULL;
  *outsize = 0;

  fd = open(CAMERA_DEV_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("ai_glasses: cannot open %s (%d)\n", CAMERA_DEV_PATH, errno);
      return -1;
    }

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width       = CAM_WIDTH;
  fmt.fmt.pix.height      = CAM_HEIGHT;
  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
  if (ret < 0)
    {
      printf("ai_glasses: VIDIOC_S_FMT failed (%d)\n", errno);
      goto errout;
    }

  memset(&req, 0, sizeof(req));
  req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;
  req.count  = 1;
  req.mode   = V4L2_BUF_MODE_RING;
  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
  if (ret < 0)
    {
      printf("ai_glasses: VIDIOC_REQBUFS failed (%d)\n", errno);
      goto errout;
    }

  buf = memalign(32, CAM_FRAME_SIZE);
  if (buf == NULL)
    {
      printf("ai_glasses: out of memory for camera frame\n");
      goto errout;
    }

  memset(&q, 0, sizeof(q));
  q.type       = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  q.memory     = V4L2_MEMORY_USERPTR;
  q.index      = 0;
  q.m.userptr  = (uintptr_t)buf;
  q.length     = CAM_FRAME_SIZE;
  ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&q);
  if (ret < 0)
    {
      printf("ai_glasses: VIDIOC_QBUF failed (%d)\n", errno);
      free(buf);
      goto errout;
    }

  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&q.type);
  if (ret < 0)
    {
      printf("ai_glasses: VIDIOC_STREAMON failed (%d)\n", errno);
      free(buf);
      goto errout;
    }

  /* DQBUF blocks until the virtual camera has filled the buffer. */

  memset(&q, 0, sizeof(q));
  q.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  q.memory = V4L2_MEMORY_USERPTR;
  ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&q);
  if (ret < 0)
    {
      printf("ai_glasses: VIDIOC_DQBUF failed (%d)\n", errno);
      ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&q.type);
      free(buf);
      goto errout;
    }

  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&q.type);
  close(fd);

  *out = buf;
  *outsize = q.bytesused > 0 ? q.bytesused : CAM_FRAME_SIZE;
  return 0;

errout:
  close(fd);
  return -1;
}

/* Simulate an on-device image-recognition inference.  First capture a real
 * frame from the camera device; then, since there is no neural network in
 * this example, return a simulated top-1 classification.  The result cycles
 * (round-robin) through every phrase that has a pre-rendered voice clip in
 * g_tts_phrases[] so the demo stays self-consistent: whatever text the
 * "recognizer" returns always has a matching clip to read it aloud.
 */

static FAR const char *image_recognition_demo(void)
{
  static unsigned int next;
  FAR uint8_t *frame = NULL;
  FAR const char *result;
  uint32_t frame_size = 0;
  uint32_t sum = 0;
  uint32_t samples = 0;
  uint32_t k;
  uint8_t avg_luma = 0;

  if (camera_grab(&frame, &frame_size) == 0 && frame != NULL)
    {
      for (k = 0; k < frame_size; k += 97)
        {
          sum += frame[k];
          samples++;
        }

      avg_luma = samples != 0 ? (uint8_t)(sum / samples) : 0;
      printf("ai_glasses: captured %lu bytes from %s (avg luma %u)\n",
             (unsigned long)frame_size, CAMERA_DEV_PATH, avg_luma);
      free(frame);
    }
  else
    {
      printf("ai_glasses: camera grab failed; using simulated frame\n");
    }

  result = g_tts_phrases[next].text;
  next = (next + 1) % TTS_PHRASE_COUNT;

  return result;
}

