/* Convert a captured QVGA RGB565 frame down to the model's 96x96 greyscale.
 * Uses simple nearest-neighbor sampling. */

static void frame_to_gray96(FAR const uint8_t *rgb565,
                            FAR uint8_t *gray96)
{
  int y;
  int x;

  for (y = 0; y < AI_GLASSES_ML_ROWS; y++)
    {
      int sy = (y * CAM_HEIGHT) / AI_GLASSES_ML_ROWS;
      for (x = 0; x < AI_GLASSES_ML_COLS; x++)
        {
          int sx = (x * CAM_WIDTH) / AI_GLASSES_ML_COLS;
          uint32_t off = (uint32_t)(sy * CAM_WIDTH + sx) * 2;
          uint16_t px = (uint16_t)(rgb565[off] | (rgb565[off + 1] << 8));
          uint8_t r = (uint8_t)((px >> 11) & 0x1f);
          uint8_t g = (uint8_t)((px >> 5) & 0x3f);
          uint8_t b = (uint8_t)(px & 0x1f);
          uint8_t r8 = (uint8_t)((r << 3) | (r >> 2));
          uint8_t g8 = (uint8_t)((g << 2) | (g >> 4));
          uint8_t b8 = (uint8_t)((b << 3) | (b >> 2));

          gray96[y * AI_GLASSES_ML_COLS + x] =
            (uint8_t)((77u * r8 + 150u * g8 + 29u * b8) >> 8);
        }
    }
}
